```c
case MAT_C_CHAR:
    ...
    matvar->data_type = MAT_T_UINT8;
    matvar->data_size = Mat_SizeOf(MAT_T_UINT8);
    err = SafeMul(&matvar->nbytes, nelems, matvar->data_size);
    ...
    matvar->data = calloc(matvar->nbytes+1, 1);
    ...
    {
        size_t nbytes;
        err = SafeMul(&nbytes, nelems, matvar->data_size);
        if ( err || nbytes > matvar->nbytes ) {
            break;
        }
    }
    if ( matvar->compression == MAT_COMPRESSION_NONE ) {
        nBytes = ReadCharData(mat,(char*)matvar->data,packed_type,(int)nelems);
```

Wait, there's a subtle issue here. `ReadCharData` reads `nelems` elements of type `packed_type`. But `packed_type` could be different from `MAT_T_UINT8`. If `packed_type` is `MAT_T_INT32`, then `ReadCharData` would read `nelems * sizeof(int32_t)` bytes into a buffer of size `nelems * sizeof(uint8_t)`.

